package main

// pdf_viewer.go
//
// Self-contained Sparrow PDF viewer/server.
// This file replaces the separate pdf_server.go + pdfjs/ directory.
// PDF.js, its worker, viewer CSS/JS, viewer HTML, and viewer image assets
// are embedded in this single Go source file.
//
// The public API intentionally matches the previous implementation:
//   sparrowPDF.ViewerURL(...)
//   sparrowPDF.OriginalFor(...)
//
// No CGO is required.

import (
	"bytes"
	"compress/gzip"
	"crypto/rand"
	"encoding/base64"
	"encoding/hex"
	"errors"
	"io"
	"net"
	"net/http"
	"net/url"
	"os"
	"path"
	"path/filepath"
	"runtime"
	"strconv"
	"strings"
	"sync"
	"time"
)

type sparrowPDFHost struct {
	mu     sync.Mutex
	base   string
	tokens map[string]string // token -> source (file path or http url)
	bySrc  map[string]string // source -> token
}

var sparrowPDF = &sparrowPDFHost{
	tokens: map[string]string{},
	bySrc:  map[string]string{},
}

var sparrowPDFClient = &http.Client{Transport: &http.Transport{
	Proxy:                 http.ProxyFromEnvironment,
	ResponseHeaderTimeout: 25 * time.Second,
}}

type sparrowPDFAsset struct {
	encoded string
	data    []byte
	once    sync.Once
}

func (a *sparrowPDFAsset) bytes() ([]byte, error) {
	var err error
	a.once.Do(func() {
		raw, e := base64.StdEncoding.DecodeString(a.encoded)
		if e != nil {
			err = e
			return
		}
		zr, e := gzip.NewReader(bytes.NewReader(raw))
		if e != nil {
			err = e
			return
		}
		defer zr.Close()
		a.data, err = io.ReadAll(zr)
	})
	if err != nil {
		return nil, err
	}
	return a.data, nil
}

