func sparrowPDFAssetType(name string) string {
	switch strings.ToLower(path.Ext(name)) {
	case ".html":
		return "text/html; charset=utf-8"
	case ".js":
		return "application/javascript; charset=utf-8"
	case ".css":
		return "text/css; charset=utf-8"
	case ".svg":
		return "image/svg+xml"
	case ".gif":
		return "image/gif"
	case ".png":
		return "image/png"
	case ".jpg", ".jpeg":
		return "image/jpeg"
	default:
		return "application/octet-stream"
	}
}

func (s *sparrowPDFHost) ensure() (string, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	if s.base != "" {
		return s.base, nil
	}

	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		return "", err
	}

	mux := http.NewServeMux()
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		if !sparrowPDFHostOK(r.Host) {
			http.Error(w, "Forbidden host", http.StatusForbidden)
			return
		}

		switch {
		case r.URL.Path == "/viewer.html":
			s.servePDFAsset(w, r, "viewer.html")
		case strings.HasPrefix(r.URL.Path, "/pdfjs/"):
			name := strings.TrimPrefix(r.URL.Path, "/pdfjs/")
			s.servePDFAsset(w, r, name)
		case strings.HasPrefix(r.URL.Path, "/doc/"):
			s.serveDoc(w, r, strings.TrimPrefix(r.URL.Path, "/doc/"))
		default:
			http.NotFound(w, r)
		}
	})

	srv := &http.Server{
		Handler:           mux,
		ReadHeaderTimeout: 5 * time.Second,
	}
	go func() { _ = srv.Serve(ln) }()

	s.base = "http://127.0.0.1:" + strconv.Itoa(ln.Addr().(*net.TCPAddr).Port)
	return s.base, nil
}

func (s *sparrowPDFHost) servePDFAsset(w http.ResponseWriter, r *http.Request, name string) {
	name = strings.TrimPrefix(name, "/")
	name = path.Clean(name)
	if name == "." || strings.HasPrefix(name, "../") || name == ".." {
		http.NotFound(w, r)
		return
	}

	asset, ok := sparrowPDFAssets[name]
	if !ok {
		http.NotFound(w, r)
		return
	}

	data, err := asset.bytes()
	if err != nil {
		http.Error(w, "PDF viewer asset error", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", sparrowPDFAssetType(name))
	w.Header().Set("Cache-Control", "public, max-age=31536000, immutable")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(data)
}

func sparrowPDFHostOK(host string) bool {
	h := strings.ToLower(host)
	return h == "127.0.0.1" || h == "localhost" ||
		strings.HasPrefix(h, "127.0.0.1:") || strings.HasPrefix(h, "localhost:")
}

// ViewerURL returns the localhost viewer address for a PDF (file:// URL,
// local path or http(s) URL).
func (s *sparrowPDFHost) ViewerURL(raw string) (string, error) {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return "", errors.New("empty pdf source")
	}

	base, err := s.ensure()
	if err != nil {
		return "", err
	}

	s.mu.Lock()
	tok, ok := s.bySrc[raw]
	if !ok {
		b := make([]byte, 16)
		if _, err := rand.Read(b); err != nil {
			s.mu.Unlock()
			return "", err
		}
		tok = hex.EncodeToString(b)
		s.bySrc[raw] = tok
		s.tokens[tok] = raw
	}
	s.mu.Unlock()

	return base + "/viewer.html?t=" + tok + "&src=" + url.QueryEscape(raw), nil
}

// OriginalFor maps a viewer URL back to the real PDF address so the address
// bar / history show the file instead of 127.0.0.1.
func (s *sparrowPDFHost) OriginalFor(loc string) string {
	s.mu.Lock()
	base := s.base
	s.mu.Unlock()

	if base == "" || !strings.HasPrefix(loc, base+"/viewer.html") {
		return loc
	}

	u, err := url.Parse(loc)
	if err != nil {
		return loc
	}

	if src := u.Query().Get("src"); src != "" {
		return src
	}
	return loc
}

func sparrowLocalPDFPath(raw string) (string, bool) {
	if strings.HasPrefix(strings.ToLower(raw), "file:") {
		u, err := url.Parse(raw)
		if err != nil {
			return "", false
		}

		p := u.Path
		// file://C:/dir/a.pdf  ("C:" ends up as the host)
		if len(u.Host) == 2 && u.Host[1] == ':' {
			return filepath.FromSlash(u.Host + p), true
		}
		// file:///C:/dir/a.pdf  ->  C:/dir/a.pdf
		if len(p) >= 3 && p[0] == '/' && p[2] == ':' {
			p = p[1:]
		}
		if runtime.GOOS == "windows" {
			if len(p) >= 3 && p[0] == '/' && p[2] == ':' {
				p = p[1:]
			}
			if u.Host != "" && !strings.EqualFold(u.Host, "localhost") {
				p = "//" + u.Host + p
			}
			p = filepath.FromSlash(p)
		}
		return p, true
	}

	if strings.Contains(raw, "://") {
		return "", false
	}

	return raw, true
}

func (s *sparrowPDFHost) serveDoc(w http.ResponseWriter, r *http.Request, token string) {
	s.mu.Lock()
	src, ok := s.tokens[token]
	s.mu.Unlock()

	if !ok {
		http.NotFound(w, r)
		return
	}

	if p, isLocal := sparrowLocalPDFPath(src); isLocal {
		f, err := os.Open(p)
		if err != nil {
			http.Error(w, "File not found", http.StatusNotFound)
			return
		}
		defer f.Close()

		st, err := f.Stat()
		if err != nil || st.IsDir() {
			http.Error(w, "Not a file", http.StatusNotFound)
			return
		}

		w.Header().Set("Content-Type", "application/pdf")
		w.Header().Set("Cache-Control", "no-store")
		http.ServeContent(w, r, filepath.Base(p), st.ModTime(), f)
		return
	}

	req, err := http.NewRequestWithContext(r.Context(), http.MethodGet, src, nil)
	if err != nil {
		http.Error(w, "Bad URL", http.StatusBadRequest)
		return
	}

	if rg := r.Header.Get("Range"); rg != "" {
		req.Header.Set("Range", rg)
	}

	req.Header.Set(
		"User-Agent",
		"Mozilla/5.0 (Windows NT 10.0; Win64; x64) Sparrow",
	)

	resp, err := sparrowPDFClient.Do(req)
	if err != nil {
		http.Error(w, "Could not fetch PDF", http.StatusBadGateway)
		return
	}
	defer resp.Body.Close()

	for _, h := range []string{"Content-Length", "Content-Range", "Accept-Ranges"} {
		if v := resp.Header.Get(h); v != "" {
			w.Header().Set(h, v)
		}
	}

	w.Header().Set("Content-Type", "application/pdf")
	w.WriteHeader(resp.StatusCode)
	_, _ = io.Copy(w, resp.Body)
}
